#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

// Exact-shape implicit-im2col Conv3d kernel
// Input:  (N, 3,  D,   H,   W)   float32 NCDHW contiguous
// Weight: (64, 3, 3, 3, 3)       float32 contiguous  -> stored in constant mem
// Output: (N, 64, D-2, H-2, W-2) float32 NCDHW contiguous
// stride=1, padding=0, dilation=1, groups=1, bias=False

#define CIN   3
#define COUT  64
#define KS    3
#define KSIZE (CIN * KS * KS * KS)  // 81

// Weight fits in constant memory: 64*81*4 = 20736 bytes < 64KB
__constant__ float c_weight[COUT * KSIZE];

// Block: 256 threads = 4 output channels x 64 spatial
// Each thread: one (oc, spatial_flat) -> one output value
// Grid: (ceil(OHW/64), N*D_out, ceil(COUT/4))
#define SPATIAL_BLOCK 64
#define OC_BLOCK_IM   4

__global__ void conv3d_im2col_kernel(
    const float* __restrict__ input,
    float* __restrict__ output,
    int N, int D, int H, int W,
    int D_out, int H_out, int W_out)
{
    // Each block: OC_BLOCK_IM output channels x SPATIAL_BLOCK spatial positions
    int sp_idx  = blockIdx.x * SPATIAL_BLOCK + threadIdx.x % SPATIAL_BLOCK;
    int oc_off  = threadIdx.x / SPATIAL_BLOCK;  // 0..OC_BLOCK_IM-1
    int nd      = blockIdx.y;  // n * D_out + od
    int oc_base = blockIdx.z * OC_BLOCK_IM;

    int n_idx = nd / D_out;
    int od    = nd % D_out;
    int oc    = oc_base + oc_off;

    // Decode spatial index -> (oh, ow)
    int oh = sp_idx / W_out;
    int ow = sp_idx % W_out;

    if (oc >= COUT || sp_idx >= H_out * W_out) return;

    // Weight pointer for this output channel
    const float* w = c_weight + oc * KSIZE;

    float acc = 0.0f;
    int w_idx = 0;

    // Input base for this (n, od, oh, ow) - input depth starts at od
    // input[n, ci, id, ih, iw] = input[(n*CIN + ci)*D*H*W + id*H*W + ih*W + iw]
    int in_n_base = n_idx * CIN * D * H * W;
    int id_base   = od;   // kd=0 -> id=od, kd=1 -> id=od+1, kd=2 -> id=od+2
    int ih_base   = oh;
    int iw_base   = ow;

    #pragma unroll
    for (int ci = 0; ci < CIN; ci++) {
        int in_c_base = in_n_base + ci * D * H * W;
        #pragma unroll
        for (int kd = 0; kd < KS; kd++) {
            int in_d_base = in_c_base + (id_base + kd) * H * W;
