            for (int kh = 0; kh < KS; kh++) {
                int in_dh_base = in_d_base + (ih_base + kh) * W;
                #pragma unroll
                for (int kw = 0; kw < KS; kw++) {
                    float ival = __ldg(input + in_dh_base + (iw_base + kw));
                    acc += ival * c_weight[oc * KSIZE + w_idx];
                    w_idx++;
