    int ow_base = tile_w * TILE_SH;
    int oh = oh_base + ty;
    int ow = ow_base + tx;
    int oc_base = oc_blk * OC_BLOCK_SH;

    const int SH = TILE_SH + KS - 1;  // 10
    const int SW = TILE_SH + KS - 1;  // 10
    __shared__ float smem[CIN][KS][SH][SW];

    int id_base = od;
    int total_load = CIN * KS * SH * SW;  // 3*3*10*10 = 900
    int tid = ty * TILE_SH + tx;
    int block_threads = TILE_SH * TILE_SH;  // 64

    for (int li = tid; li < total_load; li += block_threads) {
