    if (oh >= H_out || ow >= W_out) return;

    float acc[OC_BLOCK_SH];
    #pragma unroll
    for (int i = 0; i < OC_BLOCK_SH; i++) acc[i] = 0.0f;

    #pragma unroll
    for (int ci = 0; ci < CIN; ci++) {
        #pragma unroll
        for (int kd = 0; kd < KS; kd++) {
            #pragma unroll
            for (int kh = 0; kh < KS; kh++) {
                #pragma unroll
                for (int kw = 0; kw < KS; kw++) {
                    float ival = smem[ci][kd][ty + kh][tx + kw];
